#!/usr/bin/env bash
# tools/e2e.sh - Produkt-E2E: die Laeufe, die den Serverprozess ueber seine Aussengrenze pruefen, als Stufen
# nacheinander (TDS-QA-01, TDS-QA-06, ADR-0022). Aufruf ueber `make e2e`; kein Gate, nicht in GATE_CHECKS.
#
# Jede Stufe ruft ein `make`-Target (ein Docker-Lauf gleichzeitig) und traegt eine Deklaration
#   e2e_abdeckung "<Kennungen>" "<Kurzbeschreibung>" "<Anker>"
# aus der `make e2e-abdeckung` die Sicht docs/plan/e2e-abdeckung.md erzeugt (Marker in repo.mk). Die Sicht ist eine
# Deklaration, kein Lauf-Beleg; jede Deklaration traegt in der Kurzbeschreibung den Teil "Nicht belegt: <Rest>" (gehalten von
# `make skript-selbsttest`, der Rest ist nichtleer): dass eine Stufe ihre Kennungen traegt, belegt ihr gruener Lauf, nicht die Datei.
# Setzung: die erste rote Stufe bricht den Durchgang ab (Exit 1), und die Ausgabe nennt die Stufe; die folgenden
# Stufen laufen nicht (gehalten von `make skript-selbsttest`). Die Harness-Selbstpruefung (tools/harness/selbstpruefung.sh) ist keine Stufe.
set -u

# Aufruf der Stufen; tools/e2e-selbsttest.sh setzt E2E_MAKE auf einen Ersatz und prueft damit Abbruch und Ausgabe.
make_cmd="${E2E_MAKE:-make}"

e2e_abdeckung() { echo "abdeckung: $1 — $2 (Anker: $3)"; }

lauf() {
	local nr="$1" t0="$SECONDS"
	shift
	local anzeige="$*"
	if [ "$1" = make ]; then
		shift
		set -- "$make_cmd" "$@"
	fi
	if ! "$@"; then
		echo "e2e: ROT - Stufe $nr ($anzeige) nach $((SECONDS - t0)) s; der Durchgang bricht ab, folgende Stufen laufen nicht." >&2
		exit 1
	fi
	echo "e2e: Stufe $nr gruen ($anzeige, $((SECONDS - t0)) s)"
}

echo "e2e: Stufe 1 Rohbytes-Login und Startverhalten des Prozesses ..."
e2e_abdeckung "TDS-FA-01 TDS-FA-02 TDS-FA-07 TDS-FA-09 TDS-QA-02" "Rohbytes-Integration über die Prozessgrenze (kein Referenzclient; LOGINACK mit dem Codec der Bibliothek dekodiert, selbstkonsistent; läuft auch in make test): Kindprozess mit main des Testservers (Klassenpfad des Gradle-Moduls testserver) und Rohbytes-Client: PRELOGIN und LOGIN7 mit LOGINACK, Start mit TLS ohne JVM-Option gelingt, fehlende Pflichtoption, ungültiger LOGIN_TIMEOUT und belegter Port beenden den Start mit Exit-Code 1 und der erwarteten Diagnosezeile (Wortlaut geprüft, ohne Wert der Option); Startdiagnose und Zustandsereignisse über die Prozessgrenze (ZustandsereignisseProzessTest, Rohbytes-Client, Zeilen der Standardausgabe): der belegte Port nennt Adresse und Port in Zeile und Ereignis bind_failed, ein abgelaufener und ein unlesbarer Schlüsselspeicher nennen den Teil ohne Pfad, Inhalt und Passwort, REQUIRED ohne Speicher, TEST_UNENCRYPTED mit Speicher, eine unbekannte Richtlinie und ein Schalter außerhalb von true/false weisen den Start ab (Exit-Code 1, keine Bereitschaftszeile), ein Lauf zeigt in Reihenfolge config_effective, server_started mit Adresse und Port, die zwei Abschwächungen, connection_opened und connection_closed mit Grund, login_accepted, request_failed mit error_code, server_stopping und server_stopped, zuletzt gestoppt; Prozess-Stop (SIGTERM) mit einer ruhenden Verbindung und einer laufenden Anfrage (Tabelle laufend, Zeilen ohne Ende, SHUTDOWN_GRACE 1 s, CANCEL_TIMEOUT 1 s): der Prozess endet, die ruhende Verbindung ist getrennt, die Antwort der laufenden Anfrage endet mit DONE[ATTN]; fünf abrupte TCP-Abbrüche (RST) während einer Anfrage lassen den Prozess erreichbar und die Ausgabe ohne Ausnahme; ein beschädigtes PRELOGIN und ein Paket mit unbekanntem Typ schließen ohne Antwortbytes, der Prozess bleibt erreichbar. Nicht belegt: Referenzclient, ein TLS-Handschlag mit einem Client (der Start mit TLS belegt die Startprobe), Anfragepfad außer der Tabelle laufend, TDS_SHUTDOWN für eine nachgeschickte Anfrage über die Prozessgrenze (belegt nur im Prozess über einen Socket, ShutdownWiringTest in make test), Stop und Abbruch unter TLS oder am Referenzclient, ein Herunterfahren am echten Server, unzulässiges PRELOGIN über das beschädigte hinaus (FA-01 Negative), abweichende Clientoption (FA-01 Boundary), die Zeilen des Log-Adapters über die genannten Ereignisse hinaus (Inspektion aller Zeilen, LOG_LEVEL und Kanal ohne Leser am Prozess: TestserverLogProcessTest in make test; ein Lauf mit Massenladen, parametrisierter Anfrage, Fehler und Abbruch durch ATTENTION und die Inspektion aller Zeilen auf Pflichtfelder, Felder und Verbotenes: TestserverLaufInspektionTest in make test), Verbindungen mit LOGIN_TIMEOUT, SHUTDOWN_GRACE_EXPIRED oder über MAX_CONNECTIONS am Prozess (am Server im Prozess des Tests: ZustandsereignisseTest), Zertifikat mit falschem Namen oder Passwort des Speichers, ungültige sicherheitsrelevante Konfiguration über die geprüften Fälle hinaus (FA-09 Negative)" "make smoke"
lauf 1 make smoke

echo "e2e: Stufe 2 Testserver-Container ..."
e2e_abdeckung "TDS-RB-01 TDS-QA-06 TDS-QA-03" "Rohbytes-Integration über die Prozessgrenze (kein Referenzclient; LOGINACK mit dem Codec der Bibliothek dekodiert, selbstkonsistent): Testserver-Container startet, Login mit TEST_UNENCRYPTED aus zweitem Container gelingt, docker stop endet mit Exit-Code 143, die Ausgabe nennt weder Benutzer noch Passwort. Nicht belegt: TLS-Modus, Fehlpfade, Clean-Build in der CI (QA-06 nur der Docker-Teil)" "make laufzeittest"
lauf 2 make laufzeittest

